{
  "name": "ryanvogel-opencode-note-review",
  "version": "0.4.1",
  "description": "OpenCode TUI review-note plugin with shared note uploads and HTML/PDF report generation.",
  "type": "module",
  "types": "./dist/report.d.ts",
  "exports": {
    ".": {
      "types": "./dist/report.d.ts",
      "import": "./dist/report.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./report": {
      "types": "./dist/report.d.ts",
      "import": "./dist/report.js"
    }
  },
  "bin": {
    "ryanvogel-opencode-note-review": "dist/cli.js",
    "opencode-note-review": "dist/cli.js",
    "opencode-review": "dist/cli.js"
  },
  "files": [
    "dist/",
    "README.md",
    "docs/",
    "examples/"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "report": "bun src/cli.ts report",
    "check": "tsc -p tsconfig.json --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "model-review",
    "review-notes",
    "pdf-report"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/anomalyco/opencode-note.git"
  },
  "bugs": {
    "url": "https://github.com/anomalyco/opencode-note/issues"
  },
  "homepage": "https://github.com/anomalyco/opencode-note#readme",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest"
  },
  "devDependencies": {
    "@types/node": "latest",
    "typescript": "latest"
  },
  "engines": {
    "node": ">=20",
    "opencode": ">=1.0.0"
  }
}
